  "workerAcademyHeading": "தொழிலாளர் திறன் மேம்பாட்டு அகாடமி",
  "workerAcademySub": "நவீன பாதுகாப்பு நெறிமுறைகள் மற்றும் சான்றளிக்கப்பட்ட உபகரண கையாளுதலில் தேர்ச்சி பெற்று அதிக வருமானம் தரும் பணிகளைப் பெறுங்கள்.",
