  "workerContributionLabel": "பணியாளர்",
  "workerDispatchedDesc": "அருகிலுள்ள பணியாளர் நியமிக்கப்பட்டார் (ரமேஷ் குமார் - 1.8 கி.மீ தூரம்).",
  "workerDispatchedTitle": "பணியாளர் புறப்பட்டார்!",
  "workerEarnings": "ਕਾਮੇ ਦੀ ਕਮਾਈ",
  "workerEarningsReport": "ਕਾਮਾ ਕਮਾਈ ਰਿਪੋਰਟ",
  "workerFlowStep1Desc": "செயலில் உள்ள வேலைகள் பிரிவில் இருப்பிடம் மற்றும் ஊதிய விவரங்களுடன் வரும் கோரிக்கைகளை சரிபார்த்து, ஏற்கவும் என்பதை அழுத்தவும்.",
  "workerFlowStep1Title": "வேலையைப் பெற்று ஏற்கவும்:",
  "workerFlowStep2Desc": "\"வழியில் உள்ளேன்\" என்பதைத் தட்டவும், இதன் மூலம் வாடிக்கையாளர் உங்கள் நேரலை வருகையைக் காண முடியும்.",
  "workerFlowStep2Title": "வேலை இடத்திற்குச் செல்லவும்:",
  "workerFlowStep3Desc": "வீட்டிற்கு வந்ததும், வாடிக்கையாளரிடம் 4 இலக்க OTP குறியீட்டைக் கேட்டு வேலையைத் தொடங்க பயன்பாட்டில் உள்ளிடவும்.",
  "workerFlowStep3Title": "வேலை தொடக்க OTP ஐ உள்ளிடவும்:",
  "workerFlowStep4Desc": "வேலையை முடித்ததும் \"முடிந்தது\" எனக் குறிக்கவும். பூஜ்ஜிய தரகுடன் உங்கள் முழு ஊதியமும் உடனடியாக உங்கள் சம்பள கணக்கில் வரவு வைக்கப்படும்.",
  "workerFlowStep4Title": "வேலையை முடித்து உடனடி கட்டணம் பெறவும்:",
  "workerFlowStep5Desc": "உயர் மதிப்பீடுகளைப் பராமரிக்கவும், அகாடமி பாடங்களை முடிக்கவும், மேலும் அதிக ஊதியம் தரும் வேலைகளைப் பெற உங்கள் சுயவிவரத்தை சரிபார்க்கவும்.",
  "workerFlowStep5Title": "நம்பிக்கையை வளர்த்து திறனை மேம்படுத்தவும்:",
  "workerHowItWorksDesc": "சகாகர் கனெக்ட் பணியாளர் தளம் இடைத்தரகர்கள் இன்றி அருகிலுள்ள வாடிக்கையாளர்களுடன் உங்களை நேரடியாக இணைக்கிறது. நீங்கள் வேலை கோரிக்கைகளைப் பெறலாம், பாதுகாப்பான OTP மூலம் தளத்தில் வேலையைச் சரிபார்க்கலாம், உங்கள் கூலி லெட்ஜரில் உடனடியாகப் பணம் பெறலாம், மேலும் கூட்டுறவு சமூகப் பாதுகாப்பு நலன்களைப் பெறலாம்.",
