  "workerList": "ਕਾਮਿਆਂ ਦੀ ਸੂਚੀ",
  "workerMandatory1Desc": "வாடிக்கையாளரிடம் 4-இலக்க OTP பெறாமல் பணியைத் தொடங்க வேண்டாம்.",
  "workerMandatory1Title": "பணிக்கு முன் எப்போதும் OTP பெறவும்:",
  "workerMandatory2Desc": "உங்கள் தொழில் விவரங்களை எப்போதும் புதுப்பித்த நிலையில் வைத்திருங்கள்.",
